def walk(d, prefix):
    out = []
    for e in repo.list(d):
        p = prefix + e
        if e.endswith("/"):
            out += walk(d + e, p)
        else:
            out.append(p)
    return out

files = walk("src/", "src/")
return {
  "src_files": files,
  "remaining_slow_anywhere_in_src": repo.search("slow_path", glob="src/**"),
  "remaining_fast_in_src": repo.search("fast_path", glob="src/**"),
  "docs_content": repo.read("docs/history.txt"),
  "docs_dir": repo.list("docs/"),
}
